select date_trunc('week', signup_date) as week_start, sort_array(collect_set(country)) as country_list, count(*) as cnt, percentile_approx(age, array(0.25, 0.5, 0.75)) as age_quartiles, count(distinct country) as distinct_countries, sort_array(collect_set(city)) as city_list, round(sum(credit_limit) / nullif(count(case when city = 'London' then 1 end), 0), 2) as credit_limit_per_london from customers group by date_trunc('week', signup_date) order by credit_limit_per_london asc
